questionvariables.text:
stack_include("contribl://prooflib.mac");
proof_steps: [
 ["intro", "Let \\(n\\) be any integer. Then \\(n^3 - n = (n - 1)\\,n\\,(n + 1)\\)."],
 ["split", "Every integer is a multiple of 3, or 1 more than a multiple of 3, or 2 more than a multiple of 3. So \\(n = 3k\\), \\(n = 3k + 1\\) or \\(n = 3k + 2\\) for some integer \\(k\\)."],
 ["c0", "Case \\(n = 3k\\)."],
 ["c0f", "The factor \\(n = 3k\\) is a multiple of 3."],
 ["c1", "Case \\(n = 3k + 1\\)."],
 ["c1f", "The factor \\(n - 1 = 3k\\) is a multiple of 3."],
 ["c2", "Case \\(n = 3k + 2\\)."],
 ["c2f", "The factor \\(n + 1 = 3k + 3 = 3(k + 1)\\) is a multiple of 3."],
 ["conc", "In every case one of the factors of \\((n - 1)\\,n\\,(n + 1)\\) is a multiple of 3, so \\(n^3 - n\\) is a multiple of 3."]
];
proof_steps: random_permutation(proof_steps);
/* The three case modules commute: proof_alternatives gives all 6 orders. */
ta: proof("intro", proof_cases("split", proof("c0", "c0f"), proof("c1", "c1f"), proof("c2", "c2f")), "conc");

feedbackvariables.text:
sa: parsons_decode(ans1);
[pd, saa]: proof_assessment(sa, proof_alternatives(ta));
usedkeys: args(sa);
missingcase: not(every(lambda([c], member(c, usedkeys)), ["c0", "c1", "c2"]));
